    [7] = {
      id = 920714,
      step = 7,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=我虽然无比珍重与主厨之间的缘分，也无比敬爱主厨。但这种只会徒生是非的节日实在是与我相距甚远。",
