    [9] = {
      id = 920714,
      step = 9,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=所谓清，与浊相对，纯洁透亮，一眼可见其深。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [10] = {
      id = 920714,
      step = 10,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=所谓净，即为干净，一尘不染，与洁净之物擦身而过，既不会影响到它自身的完美，也不会从它身上沾染到污物。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
