      step = 12,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=人之所以修佛，追求的不是功名利禄，不是得道飞升，不是长命百岁，而是内心清净。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
