      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=在混乱而浑浊的世道之中，利于是非之间、善恶之际，不为执念所困，心明物与我的根源。",
      offset = 0,
      shake = 0,
